/// <summary>
/// Extension of formdataSource MarkupTrans in form MarkupTrans
/// </summary>
[ExtensionOf(formDataSourceStr(MarkupTrans, MarkupTrans))]
final class AVAMarkupTrans_MarkupTransFDS_Extension
{
}

Method.Source:
/// <summary>
/// active function of markupTrans
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret = next active();

    element.avaEnableCalcQty();

    return ret;
}

/// <summary>
/// Extension of method mcrInitFromCaller
/// </summary>
void mcrInitFromCaller()
{
    AgreementLine agreementLineLoc;
    MarkupTrans markupTransLoc = element.markupTrans;

    next mcrInitFromCaller();

    switch (element.callerTableId)
    {
        // Do not allow delete when launched from sales table or sales line.
        // The user should use the override functionality and set the misc
        // charge to 0.  This way an event is logged.
        case tableNum(PurchAgreementHeader):
            markupTransLoc.avaInitFromPurchAgreementHeader(element.args().record());
            break;

        case tableNum(AgreementLine):
            agreementLineLoc = element.args().record();
            if(agreementLineLoc.agreementHeader().getModuleType() == ModuleSalesPurch::Purch)
            {
                markupTransLoc.avaInitFromPurchAgreementLine(agreementLineLoc);
            }
            else
            {
                markupTransLoc.avaInitFromSalesAgreementLine(agreementLineLoc);
            }
            break;
    }
}
